add_filter( 'woocommerce_loop_add_to_cart_link', 'perfectpixel_loop_quantity_input', 10, 2 );
add_action( 'wp_footer', 'perfectpixel_loop_quantity_script' );

function perfectpixel_loop_quantity_input( $html, $product ) {
	if ( ! $product || ! $product->is_type( 'simple' ) || ! $product->is_purchasable() || ! $product->is_in_stock() || $product->is_sold_individually() ) {
		return $html;
	}
	$input = woocommerce_quantity_input(
		array(
			'min_value'   => $product->get_min_purchase_quantity(),
			'max_value'   => $product->get_max_purchase_quantity(),
			'input_value' => $product->get_min_purchase_quantity(),
		),
		$product,
		false
	);
	return '<div class="perfectpixel-loop-qty" style="display:flex;gap:.5em;align-items:center;justify-content:center">' . $input . $html . '</div>';
}

// Copy the typed quantity to the button's data-quantity, which ajax add to cart sends.
function perfectpixel_loop_quantity_script() {
	if ( ! function_exists( 'is_woocommerce' ) ) {
		return;
	}
	?>
	<script>
	document.addEventListener( 'input', function ( e ) {
		var input = e.target.closest( '.perfectpixel-loop-qty input.qty' );
		if ( ! input ) {
			return;
		}
		var button = input.closest( '.perfectpixel-loop-qty' ).querySelector( '.add_to_cart_button' );
		if ( button ) {
			button.setAttribute( 'data-quantity', input.value );
			if ( window.jQuery ) {
				window.jQuery( button ).data( 'quantity', input.value );
			}
		}
	} );
	</script>
	<?php
}
